from pathlib import Path

# Emscripten SDL1 maps browser touch to primary mouse events. That is enough
# for simple taps, but Pingus camera panning is implemented as a secondary
# (right-button) drag in Playfield. A native touch drag therefore cannot pan
# the level and may even assign the selected skill to a pingu at drag start.
# Capture touch before SDL sees it and expose mobile-friendly semantics:
#   short touch -> one primary SDL mouse click
#   drag        -> the original secondary-button drag used by desktop Pingus
# This keeps all actual GUI/gameplay hit-testing in the original engine.

p = Path('../web/shell.html')
s = p.read_text(encoding='utf-8')
anchor = '''      fitCanvas();\n\n      const getAudioContext = () =>'''
insert = '''      fitCanvas();\n\n      const installTouchControls = () => {\n        if (canvas.__pingusTouchControls) return;\n        canvas.__pingusTouchControls = true;\n\n        const touch = {\n          active: false,\n          dragging: false,\n          startX: 0,\n          startY: 0,\n          lastX: 0,\n          lastY: 0\n        };\n        const dragThreshold = 10; // CSS pixels; avoids accidental pans on taps.\n\n        const emitMouse = (type, x, y, button, buttons) => {\n          canvas.dispatchEvent(new MouseEvent(type, {\n            bubbles: true,\n            cancelable: true,\n            clientX: x,\n            clientY: y,\n            button,\n            buttons\n          }));\n        };\n\n        const blockNativeTouch = (event) => {\n          event.preventDefault();\n          event.stopImmediatePropagation();\n        };\n\n        canvas.addEventListener('touchstart', (event) => {\n          blockNativeTouch(event);\n          if (event.touches.length !== 1) {\n            touch.active = false;\n            touch.dragging = false;\n            return;\n          }\n\n          const point = event.touches[0];\n          canvas.focus({ preventScroll: true });\n          touch.active = true;\n          touch.dragging = false;\n          touch.startX = touch.lastX = point.clientX;\n          touch.startY = touch.lastY = point.clientY;\n\n          // Keep the original hover/capture rectangle in sync without clicking.\n          emitMouse('mousemove', point.clientX, point.clientY, 0, 0);\n        }, { capture: true, passive: false });\n\n        canvas.addEventListener('touchmove', (event) => {\n          blockNativeTouch(event);\n          if (!touch.active || event.touches.length !== 1) return;\n\n          const point = event.touches[0];\n          if (!touch.dragging &&\n              Math.hypot(point.clientX - touch.startX, point.clientY - touch.startY) >= dragThreshold) {\n            touch.dragging = true;\n            // Pingus already implements camera panning perfectly as a secondary\n            // button drag, so reuse that exact path instead of moving the camera\n            // from JavaScript.\n            emitMouse('mousemove', touch.startX, touch.startY, 0, 0);\n            emitMouse('mousedown', touch.startX, touch.startY, 2, 2);\n          }\n\n          if (touch.dragging)\n            emitMouse('mousemove', point.clientX, point.clientY, 0, 2);\n\n          touch.lastX = point.clientX;\n          touch.lastY = point.clientY;\n        }, { capture: true, passive: false });\n\n        const finishTouch = (event) => {\n          blockNativeTouch(event);\n          if (!touch.active) return;\n\n          const point = event.changedTouches?.[0];\n          const x = point?.clientX ?? touch.lastX;\n          const y = point?.clientY ?? touch.lastY;\n\n          if (touch.dragging) {\n            emitMouse('mousemove', x, y, 0, 2);\n            emitMouse('mouseup', x, y, 2, 0);\n          } else {\n            // Deliver a complete click only after we know the gesture was a tap.\n            // This prevents a camera swipe that starts over a pingu from assigning\n            // the currently selected skill before the drag threshold is crossed.\n            emitMouse('mousemove', x, y, 0, 0);\n            emitMouse('mousedown', x, y, 0, 1);\n            emitMouse('mouseup', x, y, 0, 0);\n          }\n\n          touch.active = false;\n          touch.dragging = false;\n        };\n\n        canvas.addEventListener('touchend', finishTouch, { capture: true, passive: false });\n        canvas.addEventListener('touchcancel', finishTouch, { capture: true, passive: false });\n      };\n      installTouchControls();\n\n      const getAudioContext = () =>'''

if s.count(anchor) != 1:
    raise SystemExit('touch controls shell anchor missing or duplicated')
s = s.replace(anchor, insert, 1)
p.write_text(s, encoding='utf-8')
